'use server';
/**
 * @fileOverview This file defines a Genkit flow that takes detailed project inputs
 *   and returns a budget estimate based on pre-defined cost calculations.
 *
 * @Exported Members:
 *   - `generateInitialEstimate`: Asynchronous function to generate the budget estimate.
 *   - `InitialEstimateInput`: Zod schema definition for the user-provided input.
 *   - `InitialEstimateOutput`: Zod schema definition for the flow's output.
 */

import { ai } from '@/ai/genkit';
import { z } from 'genkit';

// Schema for the input data provided by the user form
export const InitialEstimateInputSchema = z.object({
  squareFootage: z
    .number()
    .positive()
    .describe('The total square footage of the project area.'),
  planType: z.enum(['Open Plan', 'Mixed Use']).describe('The floor plan type.'),
  privateOffices: z
    .number()
    .int()
    .nonnegative()
    .describe('The number of private offices to be built.'),
  ceilingType: z.enum(['Standard', 'Open']).describe('The type of ceiling.'),
  ceilingHeight: z
    .number()
    .positive()
    .describe('The height of the ceiling in feet.'),
});
export type InitialEstimateInput = z.infer<typeof InitialEstimateInputSchema>;

// Schema for the data passed to the AI prompt, including calculated costs
const PromptInputSchema = InitialEstimateInputSchema.extend({
  totalDrywallCost: z.number(),
  totalElectricalCost: z.number(),
  totalHvacCost: z.number(),
  totalEstimatedBudget: z.number(),
  drywallRate: z.number(),
  electricalRate: z.number(),
  hvacRate: z.number(),
});

// Schema for the final output returned to the client
export const InitialEstimateOutputSchema = z.object({
  estimatedBudget: z
    .string()
    .describe(
      'A high-level estimate of the project budget, formatted as a currency string.'
    ),
  assumptions: z
    .string()
    .describe(
      'A list of assumptions used to generate the estimate, including cost rates.'
    ),
  disclaimer: z
    .string()
    .describe(
      'A disclaimer stating that this is only an initial estimate and actual costs may vary.'
    ),
});
export type InitialEstimateOutput = z.infer<typeof InitialEstimateOutputSchema>;

export async function generateInitialEstimate(
  input: InitialEstimateInput
): Promise<InitialEstimateOutput> {
  return generateInitialEstimateFlow(input);
}

const initialEstimatePrompt = ai.definePrompt({
  name: 'initialEstimatePrompt',
  input: { schema: PromptInputSchema },
  output: { schema: InitialEstimateOutputSchema },
  prompt: `You are an AI assistant specializing in providing initial budget estimates for commercial real estate renovation projects. Based on the user's input and pre-calculated costs, generate a summary.

Project Details:
- Square Footage: {{{squareFootage}}} sq ft
- Plan Type: {{{planType}}}
- Private Offices: {{{privateOffices}}}
- Ceiling Type: {{{ceilingType}}}
- Ceiling Height: {{{ceilingHeight}}} ft

Cost Breakdown:
- Drywall Work: \${{{totalDrywallCost}}}
- Electrical Work: \${{{totalElectricalCost}}}
- HVAC Work: \${{{totalHvacCost}}}

Format the output with the following structure:
Estimated Budget: A formatted string of the total estimated budget (e.g., "$500,000"). Use the 'totalEstimatedBudget' value and format it as a currency with commas.
Assumptions: A bulleted list of the assumptions made for the calculation.
- Drywall work is priced at \${{{drywallRate}}}/sq ft.
- Electrical work is priced at \${{{electricalRate}}}/sq ft.
- HVAC work is priced at \${{{hvacRate}}}/cubic ft, based on a {{{ceilingType}}} ceiling type.
- The estimate does not include costs for finishes, furniture, or major structural changes.
Disclaimer: This is a preliminary estimate and should be used for initial planning purposes only. Actual costs can vary significantly based on final design, material selection, and local market conditions.
`,
});

const generateInitialEstimateFlow = ai.defineFlow(
  {
    name: 'generateInitialEstimateFlow',
    inputSchema: InitialEstimateInputSchema,
    outputSchema: InitialEstimateOutputSchema,
  },
  async (input) => {
    const { squareFootage, ceilingHeight, ceilingType } = input;

    // 1. Drywall cost calculation
    const drywallRate = ceilingHeight <= 10 ? 10 : 12;
    const totalDrywallCost = squareFootage * drywallRate;

    // 2. Electrical cost calculation
    const electricalRate = 8;
    const totalElectricalCost = squareFootage * electricalRate;

    // 3. HVAC cost calculation
    const cubicFootage = squareFootage * ceilingHeight;
    const hvacRate = ceilingType === 'Standard' ? 15 : 20;
    const totalHvacCost = cubicFootage * hvacRate;

    // 4. Total budget calculation
    const totalEstimatedBudget =
      totalDrywallCost + totalElectricalCost + totalHvacCost;

    // 5. Prepare input for the AI prompt
    const promptInput = {
      ...input,
      totalDrywallCost,
      totalElectricalCost,
      totalHvacCost,
      totalEstimatedBudget,
      drywallRate,
      electricalRate,
      hvacRate,
    };

    // 6. Call the AI model to format the output
    const { output } = await initialEstimatePrompt(promptInput);
    
    if (!output) {
      throw new Error("Failed to get a response from the AI model.");
    }
    
    // Format the budget string if the model doesn't do it reliably.
    const formattedBudget = new Intl.NumberFormat('en-US', {
      style: 'currency',
      currency: 'USD',
      minimumFractionDigits: 0,
      maximumFractionDigits: 0,
    }).format(totalEstimatedBudget);
    
    return {
        ...output,
        estimatedBudget: formattedBudget,
    };
  }
);
